var ITEMS=[["Sine definition","sin(x) = opposite / hypotenuse in a right triangle."], ["Cosine definition","cos(x) = adjacent / hypotenuse in a right triangle."], ["Tangent definition","tan(x) = opposite / adjacent = sin(x)/cos(x)."], ["Cosecant","csc(x) = 1/sin(x)."], ["Secant","sec(x) = 1/cos(x)."], ["Cotangent","cot(x) = 1/tan(x) = cos(x)/sin(x)."], ["Tangent quotient","tan(x) = sin(x)/cos(x)."], ["Cotangent quotient","cot(x) = cos(x)/sin(x)."], ["Pythagorean identity","sin^2(x) + cos^2(x) = 1."], ["Tangent Pythagorean","1 + tan^2(x) = sec^2(x)."], ["Cotangent Pythagorean","1 + cot^2(x) = csc^2(x)."], ["Sine cofunction","sin(pi/2 - x) = cos(x)."], ["Cosine cofunction","cos(pi/2 - x) = sin(x)."], ["Sine is odd","sin(-x) = -sin(x)."], ["Cosine is even","cos(-x) = cos(x)."], ["Tangent is odd","tan(-x) = -tan(x)."], ["Sine sum formula","sin(A+B) = sin A cos B + cos A sin B."], ["Cosine sum formula","cos(A+B) = cos A cos B - sin A sin B."], ["Tangent sum formula","tan(A+B) = (tan A + tan B)/(1 - tan A tan B)."], ["Sine difference formula","sin(A-B) = sin A cos B - cos A sin B."], ["Cosine difference formula","cos(A-B) = cos A cos B + sin A sin B."], ["Tangent difference formula","tan(A-B) = (tan A - tan B)/(1 + tan A tan B)."], ["Double-angle sine","sin(2x) = 2 sin x cos x."], ["Double-angle cosine","cos(2x) = cos^2 x - sin^2 x = 2cos^2 x - 1 = 1 - 2sin^2 x."], ["Double-angle tangent","tan(2x) = 2 tan x / (1 - tan^2 x)."], ["Half-angle sine","sin(x/2) = +/- sqrt((1 - cos x)/2)."], ["Half-angle cosine","cos(x/2) = +/- sqrt((1 + cos x)/2)."], ["Half-angle tangent","tan(x/2) = sin x / (1 + cos x)."], ["Law of sines","a/sin A = b/sin B = c/sin C = 2R."], ["Law of cosines","c^2 = a^2 + b^2 - 2ab cos C."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
